#!/usr/bin/env bash
# Week-2 honest-halting installer. Run from the TokenGuard repo root.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing Week-2 files (honest halting + Pareto + NTC controller)..."
decode "src/tokenguard/llm/generate.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_week2_controller.py" << 'B64EOF'

B64EOF
echo ""; echo "Week-2 files installed. Re-apply gsm8k fix if needed, then run:"; echo "  python scripts/ntc_week2_controller.py --model Qwen/Qwen3-1.7B --benchmark gsm8k --limit 100 --max-tokens 1024 --tp-size 1"